import unittest

from solution import schedule_stages


class ScheduleStagesTests(unittest.TestCase):
    def test_schedules_prerequisites_before_dependents(self):
        stages = {
            "compile": ["fetch"],
            "fetch": [],
            "package": ("compile",),
            "test": ["compile"],
            "deploy": ["package", "test"],
        }
        result = schedule_stages(stages)
        self.assertIsInstance(result, tuple)
        self.assertEqual(set(result), set(stages))
        self.assertEqual(len(result), len(stages))
        positions = {name: index for index, name in enumerate(result)}
        for stage, prerequisites in stages.items():
            for prerequisite in prerequisites:
                self.assertLess(positions[prerequisite], positions[stage])

    def test_ready_stages_use_input_insertion_order(self):
        stages = {"third": [], "first": [], "second": []}
        self.assertEqual(schedule_stages(stages), ("third", "first", "second"))

        stages = {"a": ["base"], "b": ["base"], "base": []}
        self.assertEqual(schedule_stages(stages), ("base", "a", "b"))

    def test_empty_input(self):
        result = schedule_stages({})
        self.assertEqual(result, ())
        self.assertIsInstance(result, tuple)

    def test_outer_type(self):
        for value in (None, [], (), "stages"):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    schedule_stages(value)

    def test_invalid_stage_names_and_dependency_collections(self):
        for stages in ({"": []}, {1: []}, {"a": None}, {"a": {"b"}}, {"a": "b"}):
            with self.subTest(stages=stages):
                with self.assertRaises(ValueError):
                    schedule_stages(stages)

    def test_invalid_prerequisite_names(self):
        for prerequisite in ("", 1, None, True):
            with self.subTest(prerequisite=prerequisite):
                with self.assertRaises(ValueError):
                    schedule_stages({"a": [prerequisite]})

    def test_duplicate_unknown_and_self_dependencies(self):
        with self.assertRaises(ValueError):
            schedule_stages({"a": [], "b": ["a", "a"]})
        with self.assertRaises(ValueError):
            schedule_stages({"a": ["missing"]})
        with self.assertRaises(ValueError):
            schedule_stages({"a": ["a"]})

    def test_cycles_raise_value_error(self):
        with self.assertRaises(ValueError):
            schedule_stages({"a": ["b"], "b": ["a"]})
        with self.assertRaises(ValueError):
            schedule_stages({"ready": [], "a": ["b"], "b": ["a"]})

    def test_input_is_not_mutated_or_aliased(self):
        prerequisites = []
        stages = {"a": prerequisites, "b": ["a"]}
        result = schedule_stages(stages)
        self.assertEqual(stages, {"a": [], "b": ["a"]})
        prerequisites.append("later")
        stages["c"] = []
        self.assertEqual(result, ("a", "b"))


if __name__ == "__main__":
    unittest.main()

